def attach(image, profile):
    output = image[:2]
    if profile is not None:
        payload = b'ICC_PROFILE\0\1\1' + profile
        output += b'\xff\xe2' + struct.pack('>H', len(payload) + 2) + payload
    for marker, segment in segments(image):
        if marker != 0xe2 or not segment[4:].startswith(b'ICC_PROFILE\0'):
            output += segment
    assert coding(output) == coding(image)
    return output


def build(profile, record_bytes):
    with localcontext() as context:
        context.prec = 80
        return values(profile, json.loads(record_bytes))


def values(profile, record):
    inv = inverse(destination_matrix())
    missing = bytearray(profile)
    count = struct.unpack_from('>I', missing, 128)[0]
    matches = [i for i in range(132, 132 + count * 12, 12)
               if missing[i:i + 4] == b'A2B1']
    assert len(matches) == 1
    missing[matches[0]:matches[0] + 4] = b'A2B2'
    outputs = {}
    raw_arrays, linear_arrays, fallback_arrays = [], [], []
    manifest = []
    for name, (source_hash, packed) in zip(NAMES, RAW_RECORDS):
        source_path = ROOT / 'tests/data/inputs/formats' / f'snake-jpeg-{name}.jpg'
        image = source_path.read_bytes()
        assert hashlib.sha256(image).hexdigest() == source_hash
        header, raw = zlib.decompress(base64.b85decode(packed)).split(b'\n', 1)
        magic, width, height, depth, space, adobe, transform = header.decode().split()
        width, height, depth = int(width), int(height), int(depth)
        assert (magic, width, height, adobe) == ('CMYK', 64, 64, '1')
        assert (space, transform) == (('5', '2') if 'ycck' in name else ('4', '0'))
        samples = list(map(list, struct.iter_unpack('>4H', raw)))
        assert len(samples) == width * height
        maximum = (1 << depth) - 1
        assert all(0 <= v <= maximum for row in samples for v in row)
        # The production API expands 12-bit integer samples to full uint16.
        # Derive this source packing separately from Adobe device inversion.
        full = [[(v * 65535 + maximum // 2) // maximum for v in row]
                for row in samples] if depth == 12 else samples
        destination_max = 255 if depth == 8 else 65535
        linear = []
        gamma = []
        for sample in full:
            unit = [D(destination_max - v) / destination_max for v in sample]
            xyz = [(D(record['base_u1_15'][j]) - sum(
                unit[k] * record['weights_u1_15'][k][j] for k in range(4)))
                / 32768 for j in range(3)]
            linear.append(apply(inv, xyz))
            gamma.append([D(v) * sample[3] / (destination_max ** 2)
                          for v in sample[:3]])
        decode = lambda v: (v / D('12.92') if v <= D('.04045') else
                             ((v + D('.055')) / D('1.055')) ** D('2.4'))
        pixels = bytes(int(min(D(1), max(D(0), srgb(v))) * 255 + D('.5'))
                       for row in linear for v in row)
        outputs[f'jpeg-precision-{name}-reference.png'] = png_rgb8(64, 64, pixels)
        raw_arrays.append([samples[i] for i in WITNESS])
        linear_arrays.append([linear[i] for i in WITNESS])
        fallback_arrays.append([[gamma[i] for i in WITNESS],
            [[decode(v) for v in gamma[i]] for i in WITNESS]])
        for kind, icc in [('affine', profile), ('absent', None),
                          ('rejected', b'not an ICC profile'),
                          ('missing-intent', bytes(missing))]:
            outputs[f'jpeg-precision-{name}-{kind}.jpg'] = attach(image, icc)
        manifest.append(dict(name=name, source=str(source_path.relative_to(ROOT)),
            source_sha256=source_hash, header=header.decode(),
            raw_sha256=hashlib.sha256(raw).hexdigest(),
            coding_sha256=hashlib.sha256(coding(image)).hexdigest()))
    header = '/* Generated independent original device samples and Decimal RGB. */\n'
    header += '#ifndef SIXEL_JPEG_PRECISION_REFERENCE_H\n#define SIXEL_JPEG_PRECISION_REFERENCE_H\n'
    header += array('jp_witness', 'unsigned int', list(WITNESS))
    header += array('jp_raw', 'unsigned short', raw_arrays)
    header += array('jp_linear', 'double', linear_arrays)
    header += array('jp_fallback', 'double', fallback_arrays)
    gray_source = ROOT / 'tests/data/inputs/formats/snake-jpeg-16bit-lossless-gray-restart.jpg'
    assert hashlib.sha256(gray_source.read_bytes()).hexdigest() == '793fba2456bc0c4f9dff83c0fa97fc824e76c3eb295db77f1f783b29cdbe5b5b'
    gray_header, gray_raw = zlib.decompress(base64.b85decode(GRAY_RECORD)).split(b'\n', 1)
    assert gray_header == b'GRAY 64 64 16 1 0 0'
    gray_samples = [v[0] for v in struct.iter_unpack('>H', gray_raw)]
    assert len(gray_samples) == 4096
    header += array('jp_gray16_raw', 'unsigned short', [gray_samples[i] for i in WITNESS])
    header += '#endif\n'
    outputs['jpeg-precision.h'] = header.encode()
    result = dict(generator='tools/generate_jpeg_precision_tests.py',
        source_probe='tools/verify_jpeg_cmyk_source.c --full-precision',
        decoder='libjpeg-turbo 3.2.0; JCS_CMYK; JDCT_ISLOW; no CMM',
        arithmetic='80-digit Decimal affine PCS and independent D50 sRGB inverse',
        normalization='12-bit: (sample*65535+2047)//4095; 16-bit unchanged',
        polarity='Adobe CMYK/YCCK: full-range minus normalized device sample',
        fallback='Original full-range c*k,m*k,y*k; optional sRGB decoding',
        bounds='Existing 64u32 relative; native adds two u1.15 PCS bins',
        gray16=dict(header=gray_header.decode(), source_sha256=hashlib.sha256(gray_source.read_bytes()).hexdigest(), raw_sha256=hashlib.sha256(gray_raw).hexdigest()),
        witnesses=list(WITNESS), sources=manifest,
        files={name: hashlib.sha256(data).hexdigest() for name, data in outputs.items()})
    outputs['jpeg-precision.json'] = (json.dumps(result, indent=2) + '\n').encode()
    return outputs
